test_setup_files.csvutil_test.go:
package main

import "testing"

func TestPlainFieldsStayBare(t *testing.T) {
	got := ToCSVRow([]string{"a", "b", "c"})
	if got != "a,b,c" {
		t.Fatalf("got %q", got)
	}
}

func TestCommaTriggersQuoting(t *testing.T) {
	got := ToCSVRow([]string{"a,b", "c"})
	if got != `"a,b",c` {
		t.Fatalf("got %q", got)
	}
}

func TestEmbeddedQuoteIsDoubledAndQuoted(t *testing.T) {
	got := ToCSVRow([]string{`say "hi"`})
	want := `"say ""hi"""`
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestNewlineTriggersQuoting(t *testing.T) {
	got := ToCSVRow([]string{"line1\nline2"})
	want := "\"line1\nline2\""
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestMixedRow(t *testing.T) {
	got := ToCSVRow([]string{"plain", "has,comma", `has"quote`})
	want := `plain,"has,comma","has""quote"`
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

reference_solution.csvutil.go:
package main

import (
	"strings"
)

func escapeField(field string) string {
	needsQuoting := strings.ContainsAny(field, ",\"\n")
	if !needsQuoting {
		return field
	}
	escaped := strings.ReplaceAll(field, `"`, `""`)
	return `"` + escaped + `"`
}

func ToCSVRow(fields []string) string {
	out := make([]string, len(fields))
	for i, f := range fields {
		out[i] = escapeField(f)
	}
	return strings.Join(out, ",")
}

